/**
 * 整数の性質ユニットの系列（数Ⅰ・A 第9章）。
 *
 * 背骨設計は docs/integer_series_design.md（メイン Opus 5・2026-08-06）。
 * 系列1（お手本）はメインが実装し、系列2〜10 は並列委譲＋メイン検収（C15）。
 *
 * 出典: 池田洋介『数学Ⅰ・A 入門問題精講 改訂版』第9章 整数の性質（旺文社）の
 * 章構成を借り、問題の値はすべてオリジナルに変更（copyright-credit-vs-copy）。
 *
 * ハブ胚細胞（背骨 §0）：
 *   整数は無限にあるのに、割り算がその無限を有限に畳んでくれる。
 *   割り切れるかで素数という原子に分解し、余りで有限個の箱に分類し、
 *   余りを取り続ければ必ず終わる。
 *
 * 入力の折り方（背骨 D2・入力系の拡張は不要）：
 * - 個数・値（約数の個数／総和／gcd／lcm／余り／商）はプレーン数値
 * - 素数・倍数の「判定」は最小の素因数・個数檻・□に入る数字へ折る
 * - 互いに素かどうかは gcd の値（互いに素なら 1）で問う
 * - 証明は鎖の関節の数値（各ケースの余り・種類の個数・反例の個数）を 1 step 1 関節
 * - 不定方程式の解の組は 1 問で答えさせない（範囲で一意化して片方ずつ）
 * - n 進法の表記は「数字の並びをそのまま数値として入力」（answerDisplay に右下カッコ表記）
 */

